export const generateDocumentFromJson = (json) => {
  let document = '';

  // Medical Care Preferences Section
  document += '## MEDICAL CARE PREFERENCES\n\n';
  
  const medicalPreferences = [
    { key: 'noProlongLifeTerminal', text: 'Do not prolong life if terminally ill' },
    { key: 'comfortOnlyIfIrrev', text: 'Comfort care only if irreversibly ill' },
    { key: 'noCPR', text: 'Do not perform CPR' },
    { key: 'noArtificialFoodFluids', text: 'No artificial food or fluids' },
    { key: 'noHospitalIfAvoidable', text: 'Avoid hospitalization if possible' },
    { key: 'pregnantKeepLifeSupport', text: 'Maintain life support if pregnant' },
    { key: 'treatUntilTerminal', text: 'Treat until terminal condition confirmed' },
    { key: 'prolongLifeMax', text: 'Use all available measures to prolong life' }
  ];

  medicalPreferences.forEach(pref => {
    if (json.medicalCare[pref.key]) {
      document += `• ${pref.text}\n`; // Remove icon HTML
    }
  });

  if (json.medicalCare.additionalMedCarePreferences?.length > 0) {
    document += '\nAdditional Medical Care Instructions:\n';
    json.medicalCare.additionalMedCarePreferences.forEach(pref => {
      document += `• ${pref}\n`;
    });
  }

  // Healthcare Agent Section
  if (json.healthcareAgent?.name) {
    document += '\n## HEALTHCARE AGENT\n\n';
    document += `• Name: ${json.healthcareAgent.name}\n`;
    document += `• Relationship: ${json.healthcareAgent.relationship}\n`;
    document += `• Phone: ${json.healthcareAgent.phone}\n`;
    document += `• Email: ${json.healthcareAgent.email}\n`;
  }

  // Personal Property Section
  if (json.personalProperty?.length > 0) {
    document += '\n## PERSONAL PROPERTY DISTRIBUTION\n\n';
    json.personalProperty.forEach(item => {
      document += `• ${item}\n`;
    });
  }

  // Funeral and Memorial Wishes Section
  if (json.funeralAndMemorialWishes?.length > 0) {
    document += '\n## FUNERAL AND MEMORIAL WISHES\n\n';
    json.funeralAndMemorialWishes.forEach(wish => {
      document += `• ${wish}\n`;
    });
  }

  // Additional Instructions Section
  if (json.additionalInstructions?.length > 0) {
    document += '\n## ADDITIONAL INSTRUCTIONS\n\n';
    json.additionalInstructions.forEach(instruction => {
      document += `• ${instruction}\n`;
    });
  }

  return document;
};
