import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  defaultSystemPrompt,
  defaultAssistantPrompt,
  defaultFollowupPrompt
} from "../config/prompts";

const AdminPage = () => {
  const navigate = useNavigate();

  // Load from localStorage or use defaults
  const [apiKey, setApiKey] = useState(localStorage.getItem("groqApiKey") || "");
  const [systemPrompt, setSystemPrompt] = useState(
    localStorage.getItem("systemPrompt") || defaultSystemPrompt
  );
  const [assistantPrompt, setAssistantPrompt] = useState(
    localStorage.getItem("assistantPrompt") || defaultAssistantPrompt
  );
  const [followupPrompt, setFollowupPrompt] = useState(
    localStorage.getItem("followupPrompt-2") || defaultFollowupPrompt
  );

  const handleSave = () => {
    localStorage.setItem("groqApiKey", apiKey);
    localStorage.setItem("systemPrompt", systemPrompt);
    localStorage.setItem("followupPrompt-2", followupPrompt);
    localStorage.setItem("assistantPrompt", assistantPrompt);
    alert("Settings saved!");
  };

  return (
    <div style={{ maxWidth: 700, margin: "0 auto" }}>
      <h2>Admin: Settings</h2>
      <div style={{ marginBottom: 16 }}>
        <label>Groq API Key:</label>
        <input
          type="password"
          value={apiKey}
          onChange={e => setApiKey(e.target.value)}
          placeholder="Enter Groq API Key"
          style={{ width: "100%" }}
        />
      </div>
      <div style={{ marginBottom: 16 }}>
        <label>System Prompt:</label>
        <textarea
          value={systemPrompt}
          onChange={e => setSystemPrompt(e.target.value)}
          rows={4}
          style={{ width: "100%" }}
        />
      </div>

      <div style={{ marginBottom: 16 }}>
        <label>Assistant Prompt:</label>
        <textarea
          value={assistantPrompt}
          onChange={e => setAssistantPrompt(e.target.value)}
          rows={8}
          style={{ width: "100%" }}
        />
      </div>

      <div style={{ marginBottom: 16 }}>
        <label>Hidden Follow-up Prompt:</label>
        <textarea
          value={followupPrompt}
          onChange={e => setFollowupPrompt(e.target.value)}
          rows={10}
          style={{ width: "100%" }}
        />
      </div>

      <button onClick={handleSave} style={{ marginRight: 8 }}>Save</button>
      <button onClick={() => navigate("/")}>Return Home</button>
    </div>
  );
};

export default AdminPage;