import React, { useState, useEffect, useRef } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faThumbsUp, faThumbsDown } from '@fortawesome/free-solid-svg-icons';
import { generateDocumentFromJson } from '../services/DocumentGenerator';
import { PDFDocument } from 'pdf-lib';
import '../styles/ConversationInterface.css';
import {
  defaultSystemPrompt,
  defaultAssistantPrompt,
  defaultFollowupPrompt
} from '../config/prompts';

const assistantPrompt = localStorage.getItem("assistantPrompt") || defaultAssistantPrompt;
const systemPromptText = localStorage.getItem("systemPrompt") || defaultSystemPrompt;
const followupPrompt = localStorage.getItem("followupPrompt-2") || defaultFollowupPrompt;

const medicalPreferences = [
  { key: 'noProlongLifeTerminal', text: 'Do not prolong life if terminally ill' },
  { key: 'comfortOnlyIfIrrev', text: 'Comfort care only if irreversibly ill' },
  { key: 'noCPR', text: 'Do not perform CPR' },
  { key: 'noArtificialFoodFluids', text: 'No artificial food or fluids' },
  { key: 'noHospitalIfAvoidable', text: 'Avoid hospitalization if possible' },
  { key: 'pregnantKeepLifeSupport', text: 'Maintain life support if pregnant' },
  { key: 'treatUntilTerminal', text: 'Treat until terminal condition confirmed' },
  { key: 'prolongLifeMax', text: 'Use all available measures to prolong life' }
];

// Helper to determine if running locally (localhost or 127.0.0.1)
function isLocalhost() {
  return (
    window.location.hostname === "localhost" ||
    window.location.hostname === "127.0.0.1"
  );
}

function LivingWillModal({ open, onYes, onNo }) {
  if (!open) return null;
  return (
    <div className="modal-overlay">
      <div className="modal-content">
        <p>You have provided enough information for a living will. Would you like to download it?</p>
        <div style={{ display: 'flex', gap: '1em', justifyContent: 'center' }}>
          <button onClick={onYes}>Yes</button>
          <button onClick={onNo}>No</button>
        </div>
      </div>
    </div>
  );
}

function renderFormattedText(text) {
  // Split by lines
  const lines = text.split('\n');
  return lines.map((line, idx) => {
    // Bullet points (supports - or • at start)
    if (/^\s*([-•])\s+/.test(line)) {
      // Remove bullet char and wrap in <li>
      return <li key={idx}>{renderFormattedText(line.replace(/^\s*([-•])\s+/, ''))}</li>;
    }
    // Bold (**text**)
    const bolded = [];
    let lastIndex = 0;
    const boldRegex = /\*\*(.+?)\*\*/g;
    let match;
    let key = 0;
    while ((match = boldRegex.exec(line)) !== null) {
      if (match.index > lastIndex) {
        bolded.push(line.substring(lastIndex, match.index));
      }
      bolded.push(<strong key={key++}>{match[1]}</strong>);
      lastIndex = match.index + match[0].length;
    }
    if (lastIndex < line.length) {
      bolded.push(line.substring(lastIndex));
    }
    // If we found bold, return as <p>
    if (bolded.length > 0) {
      return <p key={idx}>{bolded}</p>;
    }
    // Otherwise, just return as <p>
    return <p key={idx}>{line}</p>;
  });
}

function extractJsonFromText(text) {
  // handle code block first
  const codeBlockMatch = text.match(/```json\s*([\s\S]*?)```/i);
  if (codeBlockMatch) {
    try {
      return JSON.parse(codeBlockMatch[1]);
    } catch (e) {}
  }
  // handle plain JSON object
  const plainJsonMatch = text.match(/({[\s\S]*})/);
  if (plainJsonMatch) {
    try {
      return JSON.parse(plainJsonMatch[1]);
    } catch (e) {}
  }
  return null;
}

const ConversationInterface = ({ onDocumentUpdate }) => {
  const [messages, setMessages] = useState([
    { id: 1, text: "Welcome to the End of Life Planning Guide. I'm here to help you make important decisions and create a document that reflects your wishes. Would you like to start with medical care preferences or personal property decisions?", sender: "assistant" }
  ]);
  const [input, setInput] = useState("");
  const [documentText, setDocumentText] = useState(
    "Date Created: " + new Date().toLocaleDateString()
  );
  const [isTyping, setIsTyping] = useState(false);
  const [fullName, setFullName] = useState('');
  const [dateOfBirth, setDateOfBirth] = useState('');
  const [address, setAddress] = useState('');
  const [city, setCity] = useState('');
  const [state, setState] = useState('');
  const [zip, setZip] = useState('');
  const [phone, setPhone] = useState('');
  const [email, setEmail] = useState('');

  const [showModal, setShowModal] = useState(false);
  const [modalDismissed, setModalDismissed] = useState(false);
  
  const [jsonData, setJsonData] = useState(null);
  const [jsonOverrides, setJsonOverrides] = useState({});
  const [votes, setVotes] = useState({}); // { [key]: 'up' | 'down' | null }
  const handleVote = (key, direction) => {
    setVotes(prev => ({
      ...prev,
      [key]: prev[key] === direction ? null : direction
    }));
    setJsonOverrides(prev => ({
    ...prev,
    [key]: direction === 'up' ? true : direction === 'down' ? false : undefined
  }));
  };

  const messagesEndRef = useRef(null);

// Helper to check if all personal info fields are filled AND prolongLifeMax is true
function canDownloadLivingWill() {
  //TODO: prevent personal info from being overwritten by AI after initial input.
  const merged = getMergedJson();
  // Simple email regex for basic validation
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return (
    fullName.trim() &&
    dateOfBirth.trim() &&
    address.trim() &&
    city.trim() &&
    state.trim() &&
    zip.trim() &&
    phone.trim() &&
    email.trim() &&
    emailRegex.test(email.trim()) &&
    merged &&
    merged.medicalCare &&
    merged.medicalCare.prolongLifeMax === true
  );
}

  // Show modal when all fields are filled and not dismissed
  useEffect(() => {
    if (canDownloadLivingWill() && !showModal && !modalDismissed) {
      setShowModal(true);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fullName, dateOfBirth, address, city, state, zip, phone, email, jsonData, jsonOverrides]);

  // Download handler (replace with your actual download logic)
  async function handleDownload() {
    // Fetch the PDF template
    const response = await fetch('/AND/AZ-LCP-Living-Will.pdf');
    const existingPdfBytes = await response.arrayBuffer();
    const pdfDoc = await PDFDocument.load(existingPdfBytes);
    const form = pdfDoc.getForm();
    // Get merged JSON data
    const merged = getMergedJson();
    // Fill personal info fields
    form.getTextField('Name').setText(merged?.firstName ? `${merged.firstName} ${merged.lastName}` : fullName);
    form.getTextField('Date of Birth').setText(merged?.dateOfBirth || dateOfBirth);
    form.getTextField('Address 1').setText(merged?.address || address);
    // Address 2: city, state, zip
    const address2 = [merged?.city || city, merged?.state || state, merged?.zip || zip].filter(Boolean).join(', ');
    form.getTextField('Address 2').setText(address2);
    form.getTextField('Phone').setText(merged?.phone || phone);
    form.getTextField('Email').setText(merged?.email || email);

    // Place an X in the form field for prolongLifeMax if true
    if (merged?.medicalCare?.prolongLifeMax === true) {
      form.getTextField('5 I want my life to be prolonged to the greatest extent possible If you initial here you should').setText('X');
    } else {
      form.getTextField('5 I want my life to be prolonged to the greatest extent possible If you initial here you should').setText('');
    }

    // Serialize the PDF and trigger download
    const pdfBytes = await pdfDoc.save();
    const blob = new Blob([pdfBytes], { type: 'application/pdf' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'LivingWill.pdf';
    a.click();
    URL.revokeObjectURL(url);
    setShowModal(false);
    setModalDismissed(true);
  }

  function handleNo() {
    setShowModal(false);
    setModalDismissed(true);
  }

  useEffect(() => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: "smooth" });
    }
  }, [messages]);

  useEffect(() => {
    if (onDocumentUpdate) {
      onDocumentUpdate(documentText);
    }
  }, [documentText, onDocumentUpdate]);
 
  // Helper for Groq API chat calls
  async function groqChat({ messages, model, stream = false }) {
    const apiKey = localStorage.getItem("groqApiKey") || "";
    const response = await fetch("https://api.groq.com/openai/v1/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${apiKey}`
      },
      body: JSON.stringify({
        model,
        messages,
        stream
      })
    });
    return response;
  }

  // Helper for Ollama API chat calls
  async function ollamaChat({ messages, model, stream = false }) {
    const response = await fetch("http://127.0.0.1:11434/api/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        model,
        messages,
        stream
      })
    });
    return response;
  }

  // Helper to get merged JSON (API data + overrides)
  const getMergedJson = () => {
    if (!jsonData) return null;
    // Only override medicalCare keys for now
    const mergedMedicalCare = {
      ...jsonData.medicalCare,
      ...jsonOverrides
    };
    return {
      ...jsonData,
      medicalCare: mergedMedicalCare
    };
  };  
  
  // Handles sending messages to the AI model and processing the response.
  const handleSend = async () => {
    if (input.trim() === "") return;
  
    // Add user message
    const newMessages = [...messages, { id: messages.length + 1, text: input, sender: "user" }];
    setMessages(newMessages);
  
    setInput("");
    setIsTyping(true);
  
    const systemPrompt = {
      role: "system",
      content: systemPromptText
    };

    const assistantPromptObj = {
      role: "assistant",
      content: assistantPrompt
    };

    const modelMessages = [
      systemPrompt,
      assistantPromptObj,
      ...newMessages.map(msg => ({
        role: msg.sender === "user" ? "user" : "assistant",
        content: msg.text
      }))
    ];
  
    // Choose API based on environment (Ollama for local, Groq for others)
    const useGroq = !isLocalhost();
    const chatApi = useGroq ? groqChat : ollamaChat;
    const model = useGroq
      ? "meta-llama/llama-4-scout-17b-16e-instruct"
      : "incept5/llama3.1-claude";

    try {
      const response = await chatApi({
        model,
        messages: modelMessages,
        stream: true
      });
  
      if (!response.ok) throw new Error("Failed to fetch AI response");
  
      const reader = response.body.getReader();
      let aiResponse = "";
      let done = false;
  
      // Add a placeholder assistant message
      setMessages(prev => [
        ...prev,
        { id: prev.length + 1, text: "", sender: "assistant" }
      ]);
      
      function processGroqLine(line, aiResponse, handleAIResponse) {
        if (line.trim().startsWith('data:')) {
          const dataStr = line.replace(/^data:\s*/, '');
          if (dataStr === '[DONE]') return aiResponse;
          try {
            const json = JSON.parse(dataStr);
            const content = json.choices?.[0]?.delta?.content;
            if (content) {
              aiResponse += content;
              handleAIResponse(aiResponse);
            }
          } catch (e) {}
        }
        return aiResponse;
      }
      
      function processOllamaLine(line, aiResponse, handleAIResponse) {
        if (line.trim()) {
          try {
            const json = JSON.parse(line);
            if (json.message && json.message.content) {
              aiResponse += json.message.content;
              handleAIResponse(aiResponse);
            }
          } catch (e) {}
        }
        return aiResponse;
      }
      
      while (!done) {
        const { value, done: doneReading } = await reader.read();
        done = doneReading;
        if (value) {
          const chunk = new TextDecoder().decode(value);
      
          // Shared handler for updating messages and document
          function handleAIResponse(responseText) {
            let parsedJson = extractJsonFromText(responseText);
            let displayText = responseText;
            if (parsedJson) {
              // Remove the JSON from the display text if present
              displayText = responseText
                .replace(/```json\s*[\s\S]*?```/i, '')
                .replace(/({[\s\S]*})/, '')
                .trim();
            }
            setMessages(prev => {
              const updated = [...prev];
              updated[updated.length - 1] = {
                ...updated[updated.length - 1],
                text: displayText
              };
              return updated;
            });
            if (parsedJson) {
              updateDocumentWithJson(parsedJson);
            }
          }
      
          const lines = chunk.split('\n');
          if (useGroq) {
            for (const line of lines) {
              aiResponse = processGroqLine(line, aiResponse, handleAIResponse);
            }
          } else {
            for (const line of lines) {
              aiResponse = processOllamaLine(line, aiResponse, handleAIResponse);
            }
          }
        }
      }
  
      // If no JSON was found, send a hidden follow-up prompt
      if (!extractJsonFromText(aiResponse)) {
        // Build a hidden extraction prompt
        const extractionPrompt = {
          role: "user",
          content: followupPrompt
        };
  
        const extractionMessages = [
          systemPrompt,
          ...newMessages.map(msg => ({
            role: msg.sender === "user" ? "user" : "assistant",
            content: msg.text
          })),
          { ...extractionPrompt }
        ];
  
        const extractionResponse = await chatApi({
          model,
          messages: extractionMessages,
          stream: false
        });
  
        if (extractionResponse.ok) {
          const data = await extractionResponse.json();
          let content = "";
          if (useGroq) {
            content = data.choices?.[0]?.message?.content || "";
          } else {
            content = data.message?.content || "";
          }
          console.log("Expected JSON response:", content);
          const parsedJson = extractJsonFromText(content);
          if (parsedJson) {
            updateDocumentWithJson(parsedJson);
          }
        }
      }
  
    } catch (error) {
      setMessages(prev => [
        ...prev,
        { id: prev.length + 1, text: "Sorry, I couldn't process your request.", sender: "assistant" }
      ]);
    } finally {
      setIsTyping(false);
    }
  };

  const updateDocumentWithJson = (json) => {
    console.log("Received JSON:", json);
    setJsonData(json);
    
    if (json.firstName || json.lastName) {
      const name = [json.firstName, json.lastName].filter(Boolean).join(' ');
      setFullName(name);
    }
    if (json.dateOfBirth) {
      setDateOfBirth(json.dateOfBirth);
    }
    if (json.address !== undefined) {
      setAddress(json.address);
    }
    if (json.city !== undefined) {
      setCity(json.city);
    }
    if (json.state !== undefined) {
      setState(json.state);
    }
    if (json.zip !== undefined) {
      setZip(json.zip);
    }
    if (json.phone !== undefined) {
      setPhone(json.phone);
    }
    if (json.email !== undefined) {
      setEmail(json.email);
    }

    // Generate document sections from JSON
    const newDocumentText = generateDocumentFromJson(json);
    setDocumentText(newDocumentText);
  };

  const renderMedicalPreferences = (json) => (
    <ul>
      {medicalPreferences.map(pref => {
        const value = json.medicalCare?.[pref.key];
        const hasVote = votes[pref.key] === 'up' || votes[pref.key] === 'down';
        // Show if true or if user has voted
        if (value === true || hasVote) {
          return (
            <li key={pref.key}>
              <span
                style={votes[pref.key] === 'down' ? { textDecoration: 'line-through', color: '#888' } : undefined}
              >
                {pref.text}
              </span>
              <span className="vote-icons">
                <span
                  className={`thumb-icon${votes[pref.key] === 'up' ? ' active' : ''}`}
                  onClick={() => handleVote(pref.key, 'up')}
                  role="button"
                  tabIndex={0}
                  aria-label="Thumbs up"
                >
                  <FontAwesomeIcon icon={faThumbsUp} />
                </span>
                <span
                  className={`thumb-icon${votes[pref.key] === 'down' ? ' active' : ''}`}
                  onClick={() => handleVote(pref.key, 'down')}
                  role="button"
                  tabIndex={0}
                  aria-label="Thumbs down"
                >
                  <FontAwesomeIcon icon={faThumbsDown} />
                </span>
              </span>
            </li>
          );
        }
        return null;
      })}
    </ul>
  );

  function renderDocumentWithMedicalPreferences() {
    const lines = documentText.split('\n');
    const elements = [];
    let inMedicalPrefs = false;
    const mergedJson = getMergedJson();
  
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
  
      // Detect the start of the Medical Care Preferences section
      if (line.startsWith('## MEDICAL CARE PREFERENCES')) {
        elements.push(<h2 key={`medpref-h2-${i}`}>MEDICAL CARE PREFERENCES</h2>);
        if (mergedJson) {
          elements.push(
            <div key="interactive-medical-preferences">
              {renderMedicalPreferences(mergedJson)}
            </div>
          );
        }
        inMedicalPrefs = true;
        continue;
      }
  
      // Skip the bullet points for medical preferences (they are rendered interactively)
      if (inMedicalPrefs && line.startsWith('• ')) {
        continue;
      }
  
      // End skipping when a non-bullet, non-empty line is found
      if (inMedicalPrefs && !line.startsWith('• ') && line.trim() !== '') {
        inMedicalPrefs = false;
      }
  
      // Render other lines as before
      if (line.startsWith('# ')) {
        elements.push(<h1 key={i}>{line.substring(2)}</h1>);
      } else if (line.startsWith('## ')) {
        elements.push(<h2 key={i}>{line.substring(3)}</h2>);
      } else if (line.startsWith('• ')) {
        elements.push(
          <li
            key={i}
            dangerouslySetInnerHTML={{ __html: line.substring(2) }}
          />
        );
      } else if (line.trim() === '') {
        elements.push(<br key={i} />);
      } else {
        elements.push(<p key={i} dangerouslySetInnerHTML={{ __html: line }} />);
      }
    }
  
    return elements;
  }

  // Simple animated dots for typing indicator
  const TypingIndicator = ({ isTyping }) => {
    const [dots, setDots] = useState('');
    useEffect(() => {
      if (!isTyping) return;
      const interval = setInterval(() => {
        setDots(d => d.length < 3 ? d + '.' : '');
      }, 500);
      return () => clearInterval(interval);
    }, [isTyping]);
    return <div className="typing-indicator">Assistant is typing{dots}</div>;
  };

  return (
    <div className="conversation-container">
      {/* Modal for living will download */}
      <LivingWillModal
        open={showModal}
        onYes={handleDownload}
        onNo={handleNo}
      />
      <div className="chat-panel">
        <div className="chat-messages">
          {messages.map((message) => (
            <div
              key={message.id}
              className={`message ${message.sender}`}
            >
              <div className="message-bubble">
                <ul style={{ margin: 0, paddingLeft: '1.2em' }}>
                  {renderFormattedText(message.text)}
                </ul>
              </div>
            </div>
          ))}
          {isTyping && <TypingIndicator isTyping={isTyping} />}
          <div ref={messagesEndRef} />
        </div>

        <div className="chat-input">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Type your message here..."
            aria-label="Your message"
            disabled={isTyping}
          />
          <button
            onClick={handleSend}
            disabled={input.trim() === "" || isTyping}
            aria-label="Send message"
          >
            Send
          </button>
        </div>
      </div>

      <div className="document-panel">
        <h2>Your AI Generated Document</h2>
        <div className="document-preview">
            <h1>END OF LIFE PLANNING DOCUMENT</h1>
<p>This document was generated based on your responses during our conversation.</p>
<p><b>Important:</b> Please review each section carefully to ensure it accurately reflects your wishes. If possible, this document should be reviewed with appropriate legal or medical professionals before use.</p>
<h2>PERSONAL INFORMATION</h2>
            <div>
              Name: <input
                type="text"
                className="document-input"
                id="fullName"
                value={fullName}
                onChange={e => setFullName(e.target.value)}
              />
            </div>
            <div>
              Date of Birth: <input
                type="text"
                className="document-input"
                id="dateOfBirth"
                value={dateOfBirth}
                onChange={e => setDateOfBirth(e.target.value)}
              />
            </div>
            <div>
              Street Address: <input
                type="text"
                className="document-input"
                id="address"
                value={address}
                onChange={e => setAddress(e.target.value)}
              />
            </div>
            <div>
              City: <input
                type="text"
                className="document-input"
                id="city"
                value={city}
                onChange={e => setCity(e.target.value)}
              />
            </div>
            <div>
              State: <input
                type="text"
                className="document-input"
                id="state"
                value={state}
                onChange={e => setState(e.target.value)}
              />
            </div>
            <div>
              Zip Code: <input
                type="text"
                className="document-input"
                id="zip"
                value={zip}
                onChange={e => setZip(e.target.value)}
              />
            </div>
            <div>
              Phone: <input
                type="text"
                className="document-input"
                id="phone"
                value={phone}
                onChange={e => setPhone(e.target.value)}
              />
            </div>
            <div>
              Email: <input
                type="text"
                className="document-input"
                id="email"
                value={email}
                onChange={e => setEmail(e.target.value)}
              />
            </div>
            {renderDocumentWithMedicalPreferences()}
        </div>
        {/* Download button appears only when all fields are filled */}
        {canDownloadLivingWill() && (
          <div style={{ textAlign: "center", marginTop: "1.5em" }}>
            <button onClick={handleDownload}>
              Download Living Will
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default ConversationInterface;
